assert.equal(sha(src),'f9ce81a9aa5174e9ced8f4c58e026c2d76032f73352b9442f2ae19846984de76');
assert.equal(sha(portal),'49752606b192ba8fb6274f49ac3c16412b29c23332f2e00950be2531e5a46347');
const {releases}=JSON.parse(fs.readFileSync(src,'utf8'));
const release=releases.find(r=>r.id==='105838-2026');
const t=release.tender;
assert.equal(t.lots.length,1);
assert.equal(t.status,'active');
assert.equal(t.tenderPeriod.endDate,'2027-01-08T12:00:00Z');
assert.match(fs.readFileSync(portal,'utf8'),/Upgrade Your Browser/);
const result={decision:'NO_BID_FOR_STANDALONE_SAMPLE',notice:release.id,buyer:release.buyer.name,source:{url:'https://www.find-tender.service.gov.uk/api/1.0/ocdsReleasePackages/105838-2026',path:src,sha256:sha(src),receipt:'TASK-179502282110'},statusInSource:t.status,deadlineInSource:t.tenderPeriod.endDate,lotScope:t.lots[0].description,variantPolicy:t.lots[0].submissionTerms.variantPolicy,submission:{url:t.submissionMethodDetails,portalReceipt:'TASK-179502480111',portalCapture:portal,sha256:sha(portal),observedPage:'Upgrade Your Browser'},noticeAwardCriteria:t.awardCriteria??t.lots[0].awardCriteria??null,noticeFullDetailsReference:t.otherRequirements.reductionCriteria,coverage:'One official notice package and one GET of the submission link. The tender pack, scored criteria, supplier eligibility, and a separate submission route for a sample were not verified. The browser response does not establish a login requirement. Later amendments were not independently checked.',reason:'The only observed lot covers a multi-POS retail analytics solution. The public evidence does not support submitting an existing data QA excerpt as a standalone response, so no excerpt was produced.',reopen:'Obtain buyer-issued evidence of a scored requirement that existing work can demonstrate and an authorized response path for that contribution, either an explicitly accepted standalone deliverable or a documented prime-supplier invitation. Verify the current deadline and bidder eligibility before preparing a response.'};
fs.writeFileSync(out,JSON.stringify(result,null,2)+'\n'); console.log(JSON.stringify({out,sha256:sha(out),decision:result.decision}));
